import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 19.99, C: 50, D: 100, E: 0.1, F: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const totalFor = async (items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

// Characterization tests: pin current behavior. Totals are floored to whole euros,
// and a 10% discount applies only when the pre-discount total is strictly > 100.
const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple lines sum', [{ sku: 'A', qty: 2 }, { sku: 'C', qty: 1 }], 70],
  ['fractional prices are floored', [{ sku: 'B', qty: 3 }], 59],
  ['exactly 100 gets no discount', [{ sku: 'D', qty: 1 }], 100],
  ['just over 100 is discounted (100.01 -> 90)', [{ sku: 'D', qty: 1 }, { sku: 'E', qty: 1 }], 90],
  ['101 -> 90.9 floored to 90', [{ sku: 'D', qty: 1 }, { sku: 'A', qty: 0 }, { sku: 'E', qty: 10 }], 90],
  ['110 -> 99', [{ sku: 'A', qty: 11 }], 99],
  ['250 -> 225', [{ sku: 'C', qty: 5 }], 225],
  ['1000 -> 900', [{ sku: 'D', qty: 10 }], 900],
  ['fractional large order (33.33 x 7 = 233.31 -> 209.979 -> 209)', [{ sku: 'F', qty: 7 }], 209],
]
for (const [name, items, expected] of cases) {
  test(name, async () => assert.equal(await totalFor(items), expected))
}

test('total is persisted and returned by GET', async () => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'C', qty: 5 }] }) })
  const order = await res.json()
  const got = await (await fetch(`${base}/orders/${order.id}`)).json()
  assert.equal(got.total, 225)
})

test('empty items rejected', async () => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
  assert.equal(res.status, 400)
})
EOF
